#define _GNU_SOURCE
#include <errno.h>
#include <limits.h>
#include <stdlib.h>
#include <sys/syscall.h>
#include <sys/types.h>
#include <unistd.h>

/*
 * The audit sandbox exposes a /proc mount from outside its PID namespace.
 * Lean 4.22 resolves /proc/<getpid()>/exe instead of /proc/self/exe. Return
 * the host-visible PID encoded by /proc/self so Lean can locate its sysroot.
 */
pid_t getpid(void) {
  char target[64];
  ssize_t length = readlink("/proc/self", target, sizeof(target) - 1);
  if (length > 0) {
    target[length] = '\0';
    char *end = NULL;
    errno = 0;
    long value = strtol(target, &end, 10);
    if (errno == 0 && end != target && *end == '\0' && value > 0 && value <= INT_MAX) {
      return (pid_t)value;
    }
  }
  return (pid_t)syscall(SYS_getpid);
}

